"""Warn about commit subjects the changelog would skip. Never fails the build.

Usage: check_commit_messages.py <base-ref>     (checks <base-ref>..HEAD)

The changelog is generated by release-please from commit subjects written as

    type(optional scope): summary          e.g.  feat(rank): add the ladder endpoint

Subjects that do not look like that are not an error, they just do not appear in
CHANGELOG.md. This script says so, so it is noticed before the merge and not after."""

import os
import re
import subprocess
import sys

TYPES = "feat|fix|perf|refactor|docs|test|chore|ci|build|style|revert"
PATTERN = re.compile(rf"^({TYPES})(\([A-Za-z0-9_./,-]+\))?!?: \S")
MAX_SUBJECT = 100


def subjects(base: str) -> list[str]:
    out = subprocess.run(
        ["git", "log", "--no-merges", "--format=%h %s", f"{base}..HEAD"],
        capture_output=True, text=True, check=True).stdout
    return [line for line in out.splitlines() if line.strip()]


def main() -> int:
    base = sys.argv[1] if len(sys.argv) > 1 else "origin/main"
    try:
        commits = subjects(base)
    except subprocess.CalledProcessError as exc:
        print(f"Could not list commits against {base}: {exc.stderr.strip()}")
        return 0

    problems: list[str] = []
    for line in commits:
        sha, _, subject = line.partition(" ")
        if not PATTERN.match(subject):
            problems.append(
                f"{sha}: not `type: summary` form, left out of the changelog: {subject}")
        elif len(subject) > MAX_SUBJECT:
            problems.append(
                f"{sha}: subject is {len(subject)} characters "
                f"(keep it under {MAX_SUBJECT}): {subject}")

    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    lines = [f"Checked {len(commits)} commit(s) against {base}.",
             "Everything is in the right form." if not problems else f"{len(problems)} to look at:"]
    lines += [f"- {p}" for p in problems]
    text = "\n".join(lines)
    print(text)
    for p in problems:
        print(f"::warning title=Commit message::{p}")
    if summary:
        with open(summary, "a") as fh:
            fh.write(text + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
